<script setup lang="ts">
import {ref,reactive,computed,onMounted} from 'vue';import {api,errorText} from '../lib/api';import type {Configuration,Target} from '../types';import Icon from '../components/Icon.vue';import Notice from '../components/Notice.vue';import Modal from '../components/Modal.vue';import EmptyState from '../components/EmptyState.vue'
const config=ref<Configuration>(),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),success=ref(''),open=ref(false),editing=ref(-1),deleting=ref<number|null>(null),query=ref('')
const blank=()=>({label:'',provider:'cloudflare' as Target['provider'],name:'',zone_id:'',domain:'',line_id:'0',token_env:'CF_API_TOKEN',secret_id_env:'DNSPOD_SECRET_ID',secret_key_env:'DNSPOD_SECRET_KEY',token:'',secretId:'',secretKey:''})
const form=reactive(blank());const filtered=computed(()=>config.value?.targets.map((target,index)=>({target,index})).filter(({target})=>`${target.label} ${target.name} ${target.domain||''}`.toLowerCase().includes(query.value.toLowerCase()))||[])
async function load(){loading.value=true;error.value='';try{config.value=await api<Configuration>('/api/admin/config')}catch(e){error.value=errorText(e)}finally{loading.value=false}}
onMounted(load)
function edit(index=-1){editing.value=index;Object.assign(form,blank(),index>=0?config.value?.targets[index]:{});formError.value='';open.value=true}
function close(){if(busy.value)return;open.value=false;form.token='';form.secretId='';form.secretKey=''}
function configured(name:string){return config.value?.credentials.some(c=>c.name===name&&c.configured)||false}
function credentialReady(target:Target){return target.provider==='cloudflare'?configured(target.token_env||'CF_API_TOKEN'):configured(target.secret_id_env||'DNSPOD_SECRET_ID')&&configured(target.secret_key_env||'DNSPOD_SECRET_KEY')}
async function update(targets:Target[],credentials:Record<string,string>={}){if(!config.value)throw new Error('请先加载配置。');config.value=await api<Configuration>('/api/admin/config',{method:'PATCH',body:{revision:config.value.revision,service:{...config.value.service,dry_run:true},targets,secrets:credentials}})}
async function save(){if(!config.value)return;busy.value=true;formError.value='';try{const target:Target={label:form.label,provider:form.provider,name:form.name,...(form.provider==='cloudflare'?{zone_id:form.zone_id,token_env:form.token_env}:{domain:form.domain,line_id:form.line_id,secret_id_env:form.secret_id_env,secret_key_env:form.secret_key_env})};const credentials:Record<string,string>={};if(form.provider==='cloudflare'&&form.token)credentials[form.token_env]=form.token;if(form.provider==='dnspod'){if(form.secretId)credentials[form.secret_id_env]=form.secretId;if(form.secretKey)credentials[form.secret_key_env]=form.secretKey}const targets=[...config.value.targets];if(editing.value<0)targets.push(target);else targets[editing.value]=target;await update(targets,credentials);busy.value=false;close();success.value='目标已保存，服务保持预览模式。请运行预览检查计划。'}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
async function remove(){if(!config.value||deleting.value===null)return;busy.value=true;formError.value='';try{await update(config.value.targets.filter((_,i)=>i!==deleting.value));deleting.value=null;success.value='同步目标已移除，真实 DNS 记录没有删除。服务已切回预览模式。'}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
</script>
<template><div class="admin-heading"><div><span class="eyebrow">DNS TARGETS</span><h1>DNS 目标</h1><p>管理域名连接与解析同步。</p></div><button class="btn primary" :disabled="!config" @click="edit()"><Icon name="plus" :size="18"/>添加目标</button></div><Notice :message="error"/><Notice :message="success" kind="success"/><div class="notice info"><Icon name="lock" :size="18"/>凭据仅保存在服务器，编辑时留空保留。修改目标会切回预览，不立即修改 DNS。</div><section class="card"><div class="card-heading split"><h2>目标列表 <span class="count-label">{{config?.targets.length??'—'}}</span></h2><button class="btn small" :disabled="loading" @click="load">刷新</button></div><div v-if="config?.targets.length" class="filter-bar"><div class="search-input"><Icon name="search" :size="18"/><input v-model="query" aria-label="搜索 DNS 目标" placeholder="搜索名称或域名"></div></div><div v-if="filtered.length" class="storage-grid"><article v-for="{target,index} in filtered" :key="index" class="storage-card"><div class="split"><span class="feature-icon"><Icon name="globe" :size="22"/></span><span :class="['badge',credentialReady(target)?'active':'pending']">{{credentialReady(target)?'凭据已配置':'待配置凭据'}}</span></div><h3>{{target.label}}</h3><div class="storage-provider">{{target.provider==='cloudflare'?'Cloudflare':'DNSPod'}}</div><dl class="detail-list"><div><dt>解析名称</dt><dd>{{target.name}}</dd></div><div><dt>{{target.provider==='cloudflare'?'区域 ID':'所属域名'}}</dt><dd class="mono">{{target.zone_id||target.domain}}</dd></div><div><dt>记录类型</dt><dd>A · IPv4</dd></div><div v-if="target.provider==='dnspod'"><dt>解析线路</dt><dd>{{target.line_id||'0'}}</dd></div></dl><div class="button-row"><button class="btn small" @click="edit(index)"><Icon name="settings" :size="15"/>编辑</button><button class="btn small danger" @click="deleting=index;formError=''">移除</button></div></article></div><EmptyState v-else :title="loading?'正在加载目标…':query?'没有匹配的目标':'暂无 DNS 目标'" :text="query?'换个关键词试试。':'添加 Cloudflare 或 DNSPod 目标，开始配置同步。'" icon="globe"><button v-if="config&&!query" class="btn primary small" @click="edit()"><Icon name="plus" :size="16"/>添加目标</button></EmptyState></section><details class="card storage-guide"><summary>如何准备 DNS 目标？</summary><p>先在 DNS 控制台创建需要同步的 A 记录。程序只更新已有记录，不创建或删除记录；优选用途通常应关闭 Cloudflare 代理。</p><p>Cloudflare 使用区域 ID 与仅限目标区域的 DNS 编辑令牌。DNSPod 使用专用子账户 SecretId / SecretKey，并授予目标域名读取和修改解析权限。</p><p>同一环境变量名称代表共享凭据。多个账户请设置不同变量名，避免覆盖其他目标的凭据。</p></details><Modal :open="open" :title="editing<0?'添加 DNS 目标':'编辑 DNS 目标'" :busy="busy" @close="close"><form @submit.prevent="save"><div class="form-grid"><label class="field">目标名称<input v-model="form.label" required maxlength="80" placeholder="例如：主域名优选"></label><label class="field">服务商<select v-model="form.provider" aria-label="服务商"><option value="cloudflare">Cloudflare</option><option value="dnspod">DNSPod</option></select></label><label class="field full">{{form.provider==='cloudflare'?'完整解析域名':'主机记录'}}<input v-model="form.name" required maxlength="253" :placeholder="form.provider==='cloudflare'?'cf.example.com':'cf 或 @'"><span class="help">使用小写 ASCII / punycode，不添加末尾点号。</span></label><template v-if="form.provider==='cloudflare'"><label class="field full">区域 ID<input v-model="form.zone_id" required pattern="[0-9a-f]{32}" maxlength="32" spellcheck="false" placeholder="32 位小写十六进制 ID"></label><label class="field full">API Token<input v-model="form.token" type="password" autocomplete="new-password" :placeholder="configured(form.token_env)?'已配置，留空保留':'输入 DNS 编辑令牌'"><span class="help">只授权需要同步的区域，不使用全局 API Key。</span></label></template><template v-else><label class="field">所属域名<input v-model="form.domain" required placeholder="example.com"></label><label class="field">线路 ID<input v-model="form.line_id" required placeholder="0"><span class="help">默认线路为 0。</span></label><label class="field full">SecretId<input v-model="form.secretId" type="password" autocomplete="new-password" :placeholder="configured(form.secret_id_env)?'已配置，留空保留':'请输入 SecretId'"></label><label class="field full">SecretKey<input v-model="form.secretKey" type="password" autocomplete="new-password" :placeholder="configured(form.secret_key_env)?'已配置，留空保留':'请输入 SecretKey'"></label></template></div><details class="disclosure"><summary>高级：凭据变量名 / 多账户</summary><div class="form-grid"><label v-if="form.provider==='cloudflare'" class="field full">Token 变量名<input v-model="form.token_env" pattern="[A-Z_][A-Z0-9_]*" required></label><template v-else><label class="field">SecretId 变量名<input v-model="form.secret_id_env" pattern="[A-Z_][A-Z0-9_]*" required></label><label class="field">SecretKey 变量名<input v-model="form.secret_key_env" pattern="[A-Z_][A-Z0-9_]*" required></label></template></div></details><Notice :message="formError"/><div class="modal-actions"><button type="button" class="btn" :disabled="busy" @click="close">取消</button><button class="btn primary" :disabled="busy">{{busy?'保存中…':'保存为预览'}}</button></div></form></Modal><Modal :open="deleting!==null" title="移除同步目标" :busy="busy" @close="deleting=null"><p>只从本服务移除「{{deleting!==null?config?.targets[deleting]?.label:''}}」，不会删除提供商上的 DNS 记录。其他目标也将切回预览模式。</p><Notice :message="formError"/><div class="modal-actions"><button class="btn" :disabled="busy" @click="deleting=null">取消</button><button class="btn danger" :disabled="busy" @click="remove">确认移除</button></div></Modal></template>
